<script lang="ts">
  import {onMount,onDestroy} from "svelte";
  import PlayingCard from "./PlayingCard.svelte";
  import { blackjackValue, evaluatePokerHand, type BlackjackSession, type PokerSession, type LeisureInput } from "../../../game/core/districtLeisure";
  let { session, oninput, onbusy = () => {} }: { session: BlackjackSession | PokerSession; oninput: (input: LeisureInput) => void; onbusy?: (busy:boolean)=>void } = $props();
  const ready = $derived(session.phase === "ready");
  const wagerUnit = $derived(session.currency === "chips" ? "筹码" : "¥");
  let busy=$state(true),timer:ReturnType<typeof setTimeout>;
  function lock(ms=850){busy=true;onbusy(true);clearTimeout(timer);timer=setTimeout(()=>{busy=false;onbusy(false);},ms);}
  function animationLength(minimum:number){const count=Math.max(session.player.length,session.dealer.length,session.kind==="poker"?session.board.length:0);return Math.max(minimum,(count-1)*80+600);}
  function act(input:LeisureInput){if(busy)return;busy=true;onbusy(true);oninput(input);lock(animationLength(session.kind==="poker"?1100:850));}
  onMount(()=>lock(animationLength(700)));onDestroy(()=>{clearTimeout(timer);onbusy(false);});
</script>

<div class="table" class:blackjack-table={session.kind === "blackjack"}>
  <div class="table-watermark">泊 月 · 德 州 小 店</div>
  <div class="shoe" aria-hidden="true"><div>✦</div><small>DEALER</small></div>
  <div class="table-label dealer-label"><span class="seat-label"><i>♠</i>庄家</span><span class="hand-value">{#if ready}{session.kind === "blackjack" ? `${blackjackValue(session.dealer).total} 点` : evaluatePokerHand([...session.dealer, ...session.board]).name}{:else}{busy ? "正在发牌…" : "暗牌待揭晓"}{/if}</span></div>
  <div class="cards dealer" style:--hand-count={session.dealer.length}>{#each session.dealer as value, index (value)}<PlayingCard value={ready || (session.kind === "blackjack" && index === 0) ? value : undefined} {index}/>{/each}</div>
  {#if session.kind === "poker"}
    <div class="board-label">{ready ? "完整公共牌 · 河牌已开" : "翻牌 · 请选择弃牌或继续"}</div>
    <div class="cards board">{#each session.board as value, index (value)}<PlayingCard value={ready || index < 3 ? value : undefined} {index}/>{/each}</div>
  {:else}<div class="felt-mark">泊 月 · 21 点</div>{/if}
  <div class="table-label player-label"><span class="seat-label"><i>♣</i>你的手牌</span><span class="hand-value" class:bust={session.kind === "blackjack" && blackjackValue(session.player).total > 21}>{session.kind === "blackjack" ? `${blackjackValue(session.player).total} 点${blackjackValue(session.player).soft ? " · 软牌" : ""}` : evaluatePokerHand([...session.player, ...session.board.slice(0, ready ? 5 : 3)]).name}</span></div>
  <div class="cards player" style:--hand-count={session.player.length}>{#each session.player as value, index (value)}<PlayingCard {value} {index}/>{/each}</div>
  <div class="chips"><span class="chip-stack" aria-hidden="true"><i></i><i></i><i></i></span><span>已投入 <b>{session.paid}</b> {wagerUnit === "¥" ? "元" : wagerUnit}</span><span class="round-duration">{session.durationMinutes} 分钟一局</span></div>
</div>
{#if !ready}
  <div class="controls">
    {#if session.kind === "blackjack"}<button disabled={busy} onclick={() => act({ type: "hit" })}>补一张牌</button><button class="gold" disabled={busy} onclick={() => act({ type: "stand" })}>停牌 · 开庄</button>
    {:else}<button disabled={busy} onclick={() => act({ type: "fold" })}>弃牌 · 不追加</button><button class="gold" disabled={busy} onclick={() => act({ type: "continue" })}>继续 · 追加 {wagerUnit}{session.bet}</button>{/if}
  </div>
{/if}
<details class="rules"><summary>牌桌规则与赔率</summary><p>一副 52 张牌，无放回发牌。{#if session.kind === "blackjack"}A 计 1 或 11，J/Q/K 计 10。庄家不足 17 补牌、软 17 停牌。玩家爆牌输；双方同点且都未爆牌时平局退注。天然 21 点优先于补牌得到的 21 点，双方天然则平局。普通胜利返还底注的 2 倍（净赚 1 倍），天然 21 点返还 2.5 倍（净赚 1.5 倍）。{:else}两张手牌与五张公共牌中选最强五张，牌型相同再比较踢脚牌，花色不分大小。先看翻牌，继续需追加同额底注，再开转牌与河牌；弃牌损失已付底注。胜利返还总投入的 2 倍（含本金），最佳五张相同则平局分池，退回底注与追加注。{/if}</p></details>

