sition:absolute;z-index:5;bottom:80px;left:50%;transform:translateX(-50%);box-sizing:border-box;padding:12px 18px;max-height:45vh;overflow:auto;border:1px solid #d6c49555;border-radius:10px;background:#132e28f5;width:min(600px,calc(100% - 24px))}.rules p{margin:5px 0}@media(max-width:480px){.table{padding:10px 0;--card-width:clamp(48px,12vw,68px);gap:8px}.table-label{min-width:80vw;font-size:11px}.cards{gap:6px}.controls{gap:8px}.controls button{font-size:12px}.table-watermark{letter-spacing:3px;font-size:20px}}@media(max-height:500px) and (min-width:500px){.table{--card-width:48px;padding:2px 0;gap:1px}.table-label{font-size:10px;min-width:350px}.cards{gap:8px}.board-label{font-size:10px}.chips{font-size:10px}.felt-mark{font-size:16px}.controls{margin:4px auto 0}.controls button{min-height:36px;font-size:12px}.rules{position:absolute;right:12px;bottom:13px;width:130px;max-width:20vw}.rules[open]{right:auto;bottom:60px;max-width:none}.rules summary{font-size:10px}}
 .table{width:min(900px,100%);box-sizing:border-box;margin:0 auto;--card-width:clamp(61px,10.4vh,104px);gap:9px;padding:9px 25px}.table.blackjack-table{grid-template-rows:auto minmax(0,1fr) auto auto minmax(0,1fr) auto}.blackjack-table .felt-mark{grid-row:auto;font-size:14px;letter-spacing:7px;padding:7px 0}.table-watermark{font-size:clamp(18px,3vw,35px);color:#c6d6b914}.table-label{align-items:center;font-size:11px;min-width:min(500px,80vw);color:#b5cbb5}.seat-label{display:flex;align-items:center;gap:9px}.seat-label i{width:23px;height:23px;border:1px solid #d2c19044;border-radius:50%;display:grid;place-items:center;font:14px Georgia;color:#dbc58c;background:#153729}.hand-value{padding:4px 11px;border:1px solid #c1d4ac22;background:#0b2b22aa;border-radius:20px;color:#dfd7b6;font-variant-numeric:tabular-nums}.hand-value.bust{background:#6e393a99;color:#f1c5b4;border-color:#cf777855}.cards{gap:13px;--deal-x:100px;--deal-y:-45px}.cards.player{--deal-y:-130px}.board{padding:8px 15px;border:1px solid #c1d4ac20;border-radius:15px;background:#0b2d241a}.board-label{color:#91b39a;font-size:10px;letter-spacing:1px}.shoe{position:absolute;right:8px;top:24%;color:#8aa18c;text-align:center;transform:rotate(12deg);pointer-events:none;opacity:.7}.shoe>div{display:grid;place-items:center;width:46px;height:65px;border:3px solid #c5c6ae;border-radius:5px;background:repeating-linear-gradient(45deg,#183b32 0 2px,#264d3d 2px 4px);font:25px Georgia;color:#ccb47d;box-shadow:2px 3px #899b86,4px 6px #657b6c,6px 9px #304c3d,9px 14px 15px #0005}.shoe small{display:block;margin-top:12px;font-size:7px;letter-spacing:2px}.chips{display:flex;align-items:center;justify-content:center;gap:11px;font-size:11px;padding-top:7px;color:#acc3ac}.chips b{color:#f0d596;font-size:17px;margin:0 4px;font-variant-numeric:tabular-nums}.chip-stack{position:relative;height:27px;width:29px;margin-right:5px;text-shadow:none;letter-spacing:0}.chip-stack i{position:absolute;left:0;top:9px;width:25px;height:17px;border:3px dashed #d5caa8;background:#874b49;border-radius:50%;box-shadow:0 2px #502a28;box-sizing:border-box}.chip-stack i:nth-child(2){top:5px;background:#345b87}.chip-stack i:nth-child(3){top:1px;background:#8a6951}.round-duration{font-size:10px;color:#799e84;padding-left:10px;border-left:1px solid #b5c59a33}.controls button{transition:transform .16s,background .2s;min-height:47px;background:#113c2f;border-color:#b7c39b55;box-shadow:0 4px 0 #0c241e,0 10px 15px #001c221f}.controls button:hover:not(:disabled){transform:translateY(-2px);background:#1e4d3a}.controls button:active:not(:disabled){transform:translateY(2px)}.controls button.gold{background:linear-gradient(110deg,#e5cd94,#b99c69);box-shadow:0 4px 0 #806b45,0 10px 15px #001c221f}.rules{color:#8eaf93;font-size:10px}.rules summary{font-size:10px;min-height:26px}.controls button:focus-visible{outline:2px solid #f1dbad;outline-offset:4px}
